<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { get, getAll, post, printRecord } from '../services/api'
import { date, duration, percent } from '../services/format'
import { useFeedback } from '../composables/useFeedback'
import type { Assignment, JsonRecord } from '../types'
import NoticeBox from '../components/NoticeBox.vue'
import StatusBadge from '../components/StatusBadge.vue'
import LearningPlayer from './LearningPlayer.vue'

const props = defineProps<{ identity?: string; hash: string }>()
defineEmits<{ logout: [] }>()
const me = ref<JsonRecord>({}), assignments = ref<Assignment[]>([]), selected = ref<Assignment | null>(null), learning = ref<JsonRecord | null>(null)
const invite = ref(''), accepted = ref(false), lastSubscriptionId = ref(''), showRecords = ref(false)
const { busy, error, success, run } = useFeedback()
const active = computed(() => me.value.bindingStatus === 'ACTIVE')
const fromHash = computed(() => new URLSearchParams(props.hash.split('?')[1] || ''))
let poll: ReturnType<typeof setInterval>
async function refresh() { me.value = await get('/me'); if (active.value) assignments.value = await getAll<Assignment>('/me/assignments') }
async function refreshSelected() { if (selected.value) selected.value = await get<Assignment>(`/me/assignments/${selected.value.id}/progress`) }
async function followNotice() { const id = fromHash.value.get('assignmentId'); if (active.value && id) await open(id, fromHash.value.get('notificationId') || undefined) }
onMounted(async () => { await run(async () => { await refresh(); await followNotice() }); poll = setInterval(() => { if (me.value.bindingStatus === 'PENDING') refresh().then(() => { if (active.value) void followNotice() }).catch(() => {}) }, 3000) })
onUnmounted(() => clearInterval(poll))
watch(() => props.hash, () => { if (active.value) void run(followNotice) })
async function bind() { await run(async () => { await post('/me/binding-requests', { inviteCode: invite.value.trim() }); invite.value = ''; await refresh() }, '已提交绑定，请等待管理员核对。') }
async function subscribe(result = 'accept') { await run(async () => { if (me.value.providerMode !== 'mock') throw new Error('请在正式微信小程序内主动申请订阅，此浏览器入口只支持本地模拟。'); const request = await post('/me/subscriptions'); await post(`/me/subscriptions/${request.id || request.requestId}/result`, { nonce: request.nonce, result }); lastSubscriptionId.value = request.id || request.requestId }, result === 'accept' ? '已记录本地模拟订阅。此操作不代表真实微信授权。' : '已记录本地模拟拒绝，仍可正常学习。') }
async function open(id: string, notificationId?: string) { await run(async () => { const data = await get<Assignment>(`/me/assignments/${id}`); await post(`/me/assignments/${id}/entered`, notificationId ? { notificationId } : {}); selected.value = data; accepted.value = false; learning.value = null }) }
async function confirmLearning() { if (!selected.value || !accepted.value) return; await run(async () => { await post(`/me/assignments/${selected.value!.id}/confirm`, { progressDigest: selected.value!.progressDigest, confirmationTextVersion: selected.value!.confirmationTextVersion || 'mvp-1', accepted: true }); await refreshSelected(); await refresh() }, '本人确认已保存。本任务学习要求已完成。') }
async function returnFromLearning() { learning.value = null; await run(async () => { await refreshSelected(); await refresh() }) }
</script>
<template>
  <div class="learner-shell"><header class="learner-header"><div class="brand-mark dark">永森油服<span>企业培训</span></div><div class="actions"><span class="small">{{ me.person?.name || identity || '学员' }}</span><button class="link" @click="run(refresh)" data-testid="learner-refresh-binding">刷新身份</button><button class="link" @click="$emit('logout')" data-testid="logout">退出</button></div></header>
    <div class="local-ribbon">LOCAL 浏览器学员预览 · 模拟微信身份 {{ identity }} · 正式入口为微信小程序</div>
    <main class="learner-content"><NoticeBox :text="error" kind="error" /><NoticeBox :text="success" kind="success" />
      <section v-if="!active" class="panel binding-card"><p class="eyebrow">企业培训</p><h1>加入你的企业培训</h1><p class="muted">使用管理员发给本人的一次性邀请码。提交后需要管理员核对，才可进入学习任务。</p><div v-if="me.bindingStatus === 'PENDING'" class="pending-state" data-testid="binding-pending"><div class="empty-icon">◎</div><h2>身份待管理员核对</h2><p>核对完成后，任务会在这里显示。</p><button class="secondary" @click="run(refresh)" data-testid="binding-status-refresh">刷新绑定状态</button></div><form v-else @submit.prevent="bind" class="form-stack"><label>个人邀请码<input v-model="invite" required autocomplete="off" data-testid="learner-invite"></label><button class="primary large" :disabled="busy" data-testid="learner-bind">提交并等待核对</button></form></section>
      <template v-else-if="learning && selected"><LearningPlayer :key="learning.taskMaterialId || learning.id" :assignment-id="selected.id" :material="learning" @back="returnFromLearning" /></template>
      <template v-else>
        <section class="subscription-banner"><div><strong>接收学习任务提醒</strong><p>接收分配给你的培训通知，及时安排学习。未订阅也可进入任务。</p><span v-if="lastSubscriptionId" class="small muted">本地订阅测试编号：<code data-testid="subscription-id">{{ lastSubscriptionId }}</code></span></div><div class="actions"><button v-if="me.providerMode === 'mock'" class="secondary" :disabled="busy" @click="subscribe()" data-testid="learner-subscribe">LOCAL 模拟同意订阅</button><button v-else class="secondary" @click="subscribe()">在微信中订阅提醒</button><button v-if="me.providerMode === 'mock'" class="link muted small" @click="subscribe('reject')">模拟拒绝</button></div></section>
        <template v-if="selected"><button class="link back-link" @click="selected = null; run(refresh)">← 返回任务列表</button><section class="panel"><StatusBadge :value="selected.status" /><h1>{{ selected.title || selected.taskTitle }}</h1><p class="muted">{{ selected.description }}</p><p class="small muted">截止：{{ date(selected.dueAt) }}<span v-if="selected.taskStatus === 'CANCELLED'"> · 任务已取消，历史记录保留</span></p><div class="material-learning-list"><div v-for="m in selected.materials" :key="m.taskMaterialId || m.id" class="learning-material" :data-testid="`learner-material-${m.title}`"><div class="material-icon">{{ m.type === 'MP4' ? '▶' : '▤' }}</div><div class="material-info"><h3>{{ m.title }}</h3><p class="small muted">{{ m.type === 'MP4' ? duration(m.durationMs) : `${m.pageCount}页 · 每页${duration(m.rule?.minPageVisibleMs || 30000)}` }}</p><div class="progress-track"><span :style="{ width: percent(m.progress?.coverageRatio) }"></span></div><p class="small" :class="m.progress?.requirementsMet ? 'text-success' : 'muted'">{{ m.progress?.requirementsMet ? '已达到学习要求' : `学习覆盖 ${percent(m.progress?.coverageRatio)}` }}</p></div><button class="secondary" :disabled="selected.taskStatus === 'CANCELLED' || selected.status === 'COMPLETED'" @click="learning = m" data-testid="learner-start-material">{{ m.progress?.requirementsMet ? '查看 / 复学' : '开始 / 继续' }}</button></div></div></section>
          <section class="panel confirmation-panel"><h2>完成学习 · 本人确认</h2><template v-if="selected.status === 'COMPLETED'"><div class="completion-mark">✓</div><h3>已完成本任务学习要求</h3><p class="muted small">本人确认时间：{{ date(selected.confirmedAt) }}</p><button class="secondary" @click="run(() => printRecord(`/me/assignments/${selected!.id}/print`))" data-testid="learner-print">查看 / 打印本人记录</button></template><template v-else><p>{{ selected.confirmationText || '我确认由本人完成本任务所列材料的学习，并已阅读任务要求。' }}</p><label class="checkbox"><input v-model="accepted" type="checkbox" :disabled="!selected.requirementsMet || selected.taskStatus === 'CANCELLED'" data-testid="learner-confirm-checkbox">我已核对以上内容并确认</label><p v-if="!selected.requirementsMet" class="muted small">请先完成全部必学材料。进度只以服务端已确认结果为准。</p><button class="primary" :disabled="busy || !accepted || !selected.requirementsMet || selected.taskStatus === 'CANCELLED'" @click="confirmLearning" data-testid="learner-confirm">确认完成本任务学习</button></template><p class="small muted">此记录不自动代表考试、实操合格或取得行业资质。</p></section>
        </template>
        <template v-else><div class="page-heading"><div><p class="eyebrow">安全生产 · 岗位技能</p><h1>{{ showRecords ? '我的培训记录' : '你好，' + (me.person?.name || '学员') }}</h1><p>{{ showRecords ? '回顾已完成的培训，积累岗位成长。' : '立足岗位，持续提升。从这里开始你的学习任务。' }}</p></div><button class="secondary" @click="run(refresh)" data-testid="learner-refresh">刷新</button></div><div class="tab-bar"><button :class="{ active: !showRecords }" @click="showRecords = false">学习任务</button><button :class="{ active: showRecords }" @click="showRecords = true">培训记录</button></div><div class="learner-task-grid"><section v-for="a in assignments.filter(a => !showRecords || a.status === 'COMPLETED')" :key="a.id" class="panel learner-task" :data-testid="`learner-task-${a.title || a.taskTitle}`"><span v-if="a.status === 'READY_TO_CONFIRM'" class="badge pending">待完成最后一步</span><StatusBadge v-else :value="a.status" /><h2>{{ a.title || a.taskTitle || a.task?.title }}</h2><p class="small muted">截止 {{ date(a.dueAt) }}</p><button class="primary" @click="open(a.id)" data-testid="learner-open-task">{{ a.status === 'COMPLETED' ? '查看培训记录' : '进入学习任务 →' }}</button></section></div><div v-if="!assignments.length" class="panel empty">当前暂无培训安排，新的学习任务将在这里显示。</div></template>
      </template>
    </main><footer class="learner-footer">永森油服·企业培训 · 安全生产，岗位成长</footer>
  </div>
</template>
